      "content": "{\n  \"name\": \"dsh-openviking-enhance\",\n  \"version\": \"0.2.1\",\n  \"description\": \"OpenViking in the DSH web GUI: a Studio panel, a per-session memory-commit status pill with its commit timeline, and a right-sidebar tab showing what the current session retrieves.\",\n  \"type\": \"module\",\n  \"icon\": \"./icon.svg\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/index.js.map\",\n    \"lib/client.js\",\n    \"lib/client.js.map\",\n    \"cordis.patch.yml\",\n    \"icon.svg\",\n    \"CHANGELOG.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"engines\": {\n      \"dsh\": \">=0.2.0-rc.2 || >=0.2.1-rc.2\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\",\n        \"@deepseek-ai/dsh-client-ui-conversation\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node build.mjs\",\n    \"prepack\": \"node build.mjs\",\n    \"watch\": \"node build.mjs --watch\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"check\": \"pnpm run typecheck && pnpm run build\",\n    \"check:package\": \"node scripts/check-package.mjs\",\n    \"smoke\": \"node scripts/smoke-client.mjs && node scripts/smoke-host.mjs\",\n    \"test\": \"pnpm run check && pnpm run check:package && pnpm run unit && pnpm run smoke\",\n    \"unit\": \"node --test\",\n    \"release\": \"node scripts/release.mjs\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"^3.18.5\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"esbuild\": \"^0.28.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"typescript\": \"~5.7.2\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \"^0.2.0-rc.1 || ^0.2.1-rc.2\",\n    \"react\": \"^18.2.0\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24\",\n    \"dsh\": \">=0.2.0-rc.2 || >=0.2.1-rc.2\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/A2chitect/dsh-openviking-enhance.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/A2chitect/dsh-openviking-enhance/issues\"\n  },\n  \"homepage\": \"https://github.com/A2chitect/dsh-openviking-enhance#readme\",\n  \"author\": \"A2chitect\",\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"openviking\",\n    \"memory\",\n    \"observability\"\n  ]\n}\n"
