      "path": "src/host/recall-service.ts",
      "content": "/**\n * What OpenViking retrieves for one session, and why.\n *\n * This is the host behind the right-Sidebar recall panel. It asks the server the\n * same question the memory plugin asks on every turn — `POST\n * /api/v1/search/search` with `session_id` — instead of re-implementing\n * retrieval, so what the panel shows is the server's own ranking under the\n * session's own de-duplication state.\n *\n * Two things the panel needs that a single call does not give:\n *\n *  - **The query.** A recall is always about some prompt. With no explicit query\n *    the panel asks OpenViking for the session's most recent user turn\n *    (`<session>/messages.jsonl`, the plugin's own capture of the conversation)\n *    and searches for that, which is what the next recall would be about.\n *  - **Every source.** The plugin searches memories and skills; the panel also\n *    shows resources. The server ranks within one `target_uri` per call, so each\n *    source is searched at its own target and the replies are merged per bucket.\n *\n * Nothing here writes: retrieval is read-only on the server, and the session log\n * is only read.\n */\nimport type { PluginNotice, RecallBucket, RecallContent, RecallItem, RecallPayload, RecallQuerySource } from '../shared/protocol.ts'\nimport { RECALL_BUCKETS, RECALL_CONTENT_MAX_CHARS, RECALL_DEFAULT_LIMIT, RECALL_MAX_LIMIT } from '../shared/protocol.ts'\nimport type { OpenVikingApi, OvSearchItem, OvSearchResponse } from './openviking-api.ts'\nimport { resolveSessionUri } from './commit-service.ts'\nimport type { CommitService } from './commit-service.ts'\n\n/** Longest query taken from a session log; longer text is truncated, not sent whole. */\nconst MAX_QUERY_CHARS = 2000\n\nexport interface RecallServiceOptions {\n  api: OpenVikingApi\n  /** Session identity and actor peer come from the same place commits read them. */\n  commit: CommitService\n  /** How long one query's answer is reused for re-renders. */\n  cacheTtlMs?: number\n  now?: () => number\n}\n\ninterface CacheEntry {\n  at: number\n  value: RecallPayload\n}\n\nexport class RecallService {\n  private readonly options: RecallServiceOptions\n  private readonly cacheTtlMs: number\n  private readonly now: () => number\n  private readonly cache = new Map<string, CacheEntry>()\n\n  /** Plain field assignment: parameter properties cannot be type-stripped. */\n  constructor(options: RecallServiceOptions) {\n    this.options = options\n    this.cacheTtlMs = options.cacheTtlMs ?? 15000\n    this.now = options.now ?? Date.now\n  }\n\n  /**\n   * Retrieve for one session.\n   *\n   * `query` overrides the session's own last prompt: an empty string asks the\n   * session, whitespace-only is treated as absent.\n   */\n  async recall(\n    sessionId: string,\n    query?: string,\n    limit = RECALL_DEFAULT_LIMIT,\n    options: { fresh?: boolean } = {},\n  ): Promise<RecallPayload> {\n    const capped = Math.min(Math.max(Math.trunc(limit) || RECALL_DEFAULT_LIMIT, 1), RECALL_MAX_LIMIT)\n    const explicit = (query ?? '').trim().slice(0, MAX_QUERY_CHARS)\n    const cacheKey = `${sessionId}\\u0000${explicit}\\u0000${capped}`\n    const cached = this.cache.get(cacheKey)\n    if (!options.fresh && cached && this.now() - cached.at < this.cacheTtlMs) return cached.value\n\n    const value = await this.collect(sessionId, explicit, capped)\n    // Only successful, non-empty answers are worth reusing: an error is cheap to\n    // retry and caching it would pin a dead server into the panel.\n    if (value.query.text.length > 0) this.cache.set(cacheKey, { at: this.now(), value })\n    return value\n  }\n\n  private async collect(sessionId: string, explicitQuery: string, limit: number): Promise<RecallPayload> {\n    const started = this.now()\n    const warnings: PluginNotice[] = []\n    const { api, commit } = this.options\n\n    const ovSessionId = commit.ovSessionId(sessionId)\n    const peer = commit.actorPeer(sessionId) ?? null\n    const request = peer === null ? {} : { actorPeerId: peer }\n\n    const meta = await api.getSession(ovSessionId, request)\n    const sessionUri = meta.ok && meta.result ? resolveSessionUri(meta.result, ovSessionId, api.user) : null\n    if (!meta.ok) warnings.push({ code: 'sessionFailed', params: { error: meta.error ?? `HTTP ${meta.status}` } })\n\n    let queryText = explicitQuery\n    let querySource: RecallQuerySource = 'manual'\n    if (queryText.length === 0 && sessionUri !== null) {\n      const prompt = await this.sessionPrompt(sessionUri, request)\n      if (prompt === null) warnings.push({ code: 'noPrompt' })\n      else {\n        queryText = prompt\n        querySource = 'session'\n      }\n    }\n\n    const targets = searchTargets(sessionUri, api.user, peer)\n    if (queryText.length === 0) {\n      return {\n        sessionId,\n        ovSessionId,\n        sessionUri,\n        peer,\n        query: { text: '', source: querySource },\n        buckets: emptyBuckets(),\n        plan: null,\n        targets: targets.map((target) => target.uri),\n        total: 0,\n        latencyMs: this.now() - started,\n        searchedAt: new Date().toISOString(),\n        warnings,\n      }\n    }\n\n    const replies = await Promise.all(\n      targets.map((target) =>\n        api\n          .search(\n            {\n              query: queryText,\n              target_uri: target.uri,\n              limit,\n              score_threshold: 0,\n              session_id: ovSessionId,\n            },\n            request,\n          )\n          .then((reply) => ({ target, reply })),\n      ),\n    )\n\n    const merged = new Map<string, Map<string, RecallItem>>(\n      RECALL_BUCKETS.map((bucket) => [bucket, new Map<string, RecallItem>()] as const),\n    )\n    let plan: string | null = null\n    let total = 0\n    for (const { target, reply } of replies) {\n      if (!reply.ok || reply.result === null) {\n        warnings.push({ code: 'targetFailed', params: { target: target.uri, error: reply.error ?? `HTTP ${reply.status}` } })\n        continue\n      }\n      plan ??= reasoningOf(reply.result)\n      for (const bucket of RECALL_BUCKETS) {\n        const items = reply.result[bucket]\n        if (!Array.isArray(items)) continue\n        const into = merged.get(bucket)\n        if (into === undefined) continue\n        for (const item of items) {\n          if (typeof item?.uri !== 'string' || item.uri.length === 0) continue\n          total += 1\n          // The same memory can be reached from two targets; keep the better\n          // score rather than showing it twice.\n          const existing = into.get(item.uri)\n          if (existing === undefined || item.score > existing.score) into.set(item.uri, toRecallItem(item))\n        }\n      }\n    }\n\n    const buckets: RecallBucket[] = RECALL_BUCKETS.map((bucket) => ({\n      bucket,\n      items: [...(merged.get(bucket)?.values() ?? [])]\n        .sort((left, right) => right.score - left.score)\n        .slice(0, limit),\n    }))\n\n    return {\n      sessionId,\n      ovSessionId,\n      sessionUri,\n      peer,\n      query: { text: queryText, source: querySource },\n      buckets,\n      plan,\n      targets: targets.map((target) => target.uri),\n      total,\n      latencyMs: this.now() - started,\n      searchedAt: new Date().toISOString(),\n      warnings,\n    }\n  }\n\n  /** The session's most recent user prompt, from the plugin's own capture log. */\n  private async sessionPrompt(\n    sessionUri: string,\n    request: { actorPeerId?: string },\n  ): Promise<string | null> {\n    const log = await this.options.api.readText(`${sessionUri}/messages.jsonl`, request)\n    if (!log.ok || log.result === null) return null\n    return latestUserPrompt(log.result)\n  }\n\n  /** One entry's full text, for the panel's detail view. */\n  async content(uri: string): Promise<RecallContent | { error: string }> {\n    if (!uri.startsWith('viking://')) {\n      return { error: 'not-a-viking-path' }\n    }\n    const read = await this.options.api.readText(uri, { timeoutMs: 10000 })\n    if (!read.ok || read.result === null) {\n      return { error: read.error ?? `HTTP ${read.status}` }\n    }\n    const text = read.result\n    return {\n      uri,\n      text: text.slice(0, RECALL_CONTENT_MAX_CHARS),\n      truncated: text.length > RECALL_CONTENT_MAX_CHARS,\n    }\n  }\n}\n\n/**\n * The `viking://` targets one recall searches, in the plugin's own spirit.\n *\n * The user root covers the shared library; the peer's own tree is what the\n * session's own commits wrote, and is searched separately because the server\n * ranks within one target per call. Both memory targets feed the same bucket.\n */\nexport function searchTargets(\n  sessionUri: string | null,\n  user: string,\n  peer: string | null,\n): Array<{ bucket: string; uri: string }> {\n  const root = userRootOf(sessionUri) ?? `viking://user/${user}`\n  const targets: Array<{ bucket: string; uri: string }> = [{ bucket: 'memories', uri: `${root}/memories` }]\n  if (peer !== null && peer.length > 0) {\n    targets.push({ bucket: 'memories', uri: `${root}/peers/${peer}/memories` })\n  }\n  targets.push({ bucket: 'resources', uri: `${root}/resources` }, { bucket: 'skills', uri: `${root}/skills` })\n  return targets\n}\n\n/** `viking://user/<user>` from a session path, or null when it is not one. */\nexport function userRootOf(sessionUri: string | null): string | null {\n  if (sessionUri === null) return null\n  const match = /^(viking:\\/\\/user\\/[^/]+)/.exec(sessionUri)\n  return match?.[1] ?? null\n}\n\n/**\n * The last user turn in a session's `messages.jsonl`.\n *\n * The file is the memory plugin's capture of the conversation and is reset when\n * the session is archived, so it holds the turns since the last commit — exactly\n * the window a \"what would be recalled now\" question is about. Lines are JSON\n * objects with a `role` and `parts`; anything unparseable is skipped rather than\n * failing the whole read.\n */\nexport function latestUserPrompt(jsonl: string): string | null {\n  const lines = jsonl.split('\\n')\n  for (let index = lines.length - 1; index >= 0; index -= 1) {\n    const line = (lines[index] ?? '').trim()\n    if (line.length === 0) continue\n    let parsed: unknown\n    try {\n      parsed = JSON.parse(line)\n    } catch {\n      continue\n    }\n    if (parsed === null || typeof parsed !== 'object') continue\n    const record = parsed as { role?: unknown; parts?: unknown }\n    if (record.role !== 'user') continue\n    const text = textOfParts(record.parts)\n    if (text.length > 0) return text.slice(0, MAX_QUERY_CHARS)\n  }\n  return null\n}\n\nfunction textOfParts(parts: unknown): string {\n  if (!Array.isArray(parts)) return ''\n  const chunks: string[] = []\n  for (const part of parts) {\n    if (part === null || typeof part !== 'object') continue\n    const candidate = part as { type?: unknown; text?: unknown }\n    if (candidate.type === 'text' && typeof candidate.text === 'string') chunks.push(candidate.text)\n  }\n  return chunks.join('\\n').trim()\n}\n\nfunction reasoningOf(response: OvSearchResponse): string | null {\n  const reasoning = response.query_plan?.reasoning\n  return typeof reasoning === 'string' && reasoning.trim().length > 0 ? reasoning.trim() : null\n}\n\n/** Plural path segment → the singular kind a tag names. */\nconst MEMORY_KINDS: Record<string, string> = {\n  entities: 'entity',\n  events: 'event',\n  preferences: 'preference',\n  experiences: 'experience',\n  facts: 'fact',\n  knowledge: 'knowledge',\n  summaries: 'summary',\n}\n\n/**\n * The entry's own kind, read from the path the plugin writes.\n *\n * Retrieval says only `context_type` (memory/resource/skill) and this server\n * leaves `tags` empty, so `…/memories/events/2026/10/02/x.md` is the only place\n * that \"this is an event\" exists. An entry outside `memories/` has no kind.\n */\nexport function memoryTypeOf(uri: string): string {\n  const segment = /\\/memories\\/([^/]+)\\//.exec(uri)?.[1]\n  if (segment === undefined) return ''\n  return MEMORY_KINDS[segment] ?? segment\n}\n\nfunction toRecallItem(item: OvSearchItem): RecallItem {\n  return {\n    uri: item.uri,\n    score: typeof item.score === 'number' && Number.isFinite(item.score) ? item.score : 0,\n    contextType: typeof item.context_type === 'string' ? item.context_type : '',\n    memoryType: memoryTypeOf(item.uri),\n    level: typeof item.level === 'number' ? item.level : null,\n    abstract: typeof item.abstract === 'string' ? item.abstract : '',\n    tags: Array.isArray(item.tags) ? item.tags.filter((tag): tag is string => typeof tag === 'string') : [],\n  }\n}\n\nfunction emptyBuckets(): RecallBucket[] {\n  return RECALL_BUCKETS.map((bucket) => ({ bucket, items: [] }))\n}\n"
    },
    {
      "path": "src/host/openviking-api.ts",
      "content": "/**\n * Thin, dependency-free client for the OpenViking HTTP API.\n *\n * Only the routes this feature needs are implemented, and every one of them was\n * verified against a live OpenViking 0.4.22 server:\n *\n *   GET /health                                     liveness + version\n *   GET /api/v1/sessions/{id}                       commit state for a session\n *   GET /api/v1/fs/ls?uri=…                         history archive listing\n *   GET /api/v1/content/read?uri=…                  memory_diff.json (JSON *string*)\n *   GET /api/v1/tasks?resource_id=…                 in-flight commit tasks\n *   POST /api/v1/search/search                      session-aware retrieval\n *\n * Design rules:\n *  - every method resolves; nothing throws on a dead server or an HTTP error,\n *    because a plugin route must never take a request (or the host) down;\n *  - request timeouts are mandatory so a hung server cannot wedge the GUI;\n *  - responses come back either bare (`/health`) or enveloped\n *    (`{status, result, error}`) — `unwrap` handles both.\n */\nimport type { CommitTask } from '../shared/protocol.ts'\nimport type { OvConnection } from './config.ts'\n\nexport interface OvResult<T> {\n  ok: boolean\n  status: number\n  result: T | null\n  error: string | null\n}\n\nexport interface OvSessionMeta {\n  session_id: string\n  /**\n   * Canonical `viking://` path of the session. The server's own answer, so it is\n   * the only reliable source for the history directory: a session may live under\n   * another user or peer than the identity this plugin reads as.\n   */\n  uri?: string\n  /** Owner of the session; the fallback when `uri` is absent. */\n  created_by_user_id?: string\n  user?: { account_id?: string; user_id?: string }\n  message_count: number\n  commit_count: number\n  memories_extracted: { total: number; memory_write: number; memory_edit: number }\n  last_commit_at: string | null\n  last_auto_commit_at?: string | null\n  pending_tokens: number\n  keep_recent_count?: number\n  created_at?: string\n  updated_at?: string\n}\n\nexport interface OvFsEntry {\n  uri: string\n  size: number\n  isDir: boolean\n  modTime: string | null\n  abstract?: string\n}\n\n/** A commit task as the server returns it; the shared shape is what we rely on. */\nexport type OvCommitTask = CommitTask & { task_type?: string }\n\ninterface RequestOptions {\n  /** Actor peer for peer-scoped sessions. Omitted when the peer is unknown. */\n  actorPeerId?: string | undefined\n  timeoutMs?: number\n}\n\nconst DEFAULT_TIMEOUT_MS = 8000\n\nexport class OpenVikingApi {\n  private readonly connection: OvConnection\n\n  /** Plain field assignment: parameter properties cannot be type-stripped. */\n  constructor(connection: OvConnection) {\n    this.connection = connection\n  }\n\n  private headers(options: RequestOptions): Record<string, string> {\n    const headers: Record<string, string> = { 'Content-Type': 'application/json' }\n    if (this.connection.apiKey) headers.Authorization = `Bearer ${this.connection.apiKey}`\n    if (this.connection.account) headers['X-OpenViking-Account'] = this.connection.account\n    if (this.connection.user) headers['X-OpenViking-User'] = this.connection.user\n    if (options.actorPeerId) headers['X-OpenViking-Actor-Peer'] = options.actorPeerId\n    return headers\n  }\n\n  /** One request; resolves to a result envelope and never throws. */\n  private async request<T>(\n    path: string,\n    options: RequestOptions = {},\n    init: { method?: string; body?: unknown } = {},\n  ): Promise<OvResult<T>> {\n    const controller = new AbortController()\n    const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? DEFAULT_TIMEOUT_MS)\n    try {\n      const response = await fetch(`${this.connection.endpoint}${path}`, {\n        method: init.method ?? 'GET',\n        headers: this.headers(options),\n        signal: controller.signal,\n        ...(init.body === undefined ? {} : { body: JSON.stringify(init.body) }),\n      })\n      const body: unknown = await response.json().catch(() => null)\n      if (!response.ok) {\n        return {\n          ok: false,\n          status: response.status,\n          result: null,\n          error: extractError(body) ?? `HTTP ${response.status}`,\n        }\n      }\n      return { ok: true, status: response.status, result: unwrap<T>(body), error: null }\n    } catch (error) {\n      return {\n        ok: false,\n        status: 0,\n        result: null,\n        error: error instanceof Error ? error.message : String(error),\n      }\n    } finally {\n      clearTimeout(timer)\n    }\n  }\n\n  /** `/health` answers bare, without the `{status, result}` envelope. */\n  async health(): Promise<{ ok: boolean; version: string | null; authMode: string | null; error: string | null }> {\n    const response = await this.request<Record<string, unknown>>('/health', { timeoutMs: 4000 })\n    if (!response.ok) return { ok: false, version: null, authMode: null, error: response.error }\n    const body = response.result\n    return {\n      ok: body?.healthy === true || body?.status === 'ok',\n      version: typeof body?.version === 'string' ? body.version : null,\n      authMode: typeof body?.auth_mode === 'string' ? body.auth_mode : null,\n      error: null,\n    }\n  }\n\n  async getSession(ovSessionId: string, options: RequestOptions = {}): Promise<OvResult<OvSessionMeta>> {\n    return this.request<OvSessionMeta>(`/api/v1/sessions/${encodeURIComponent(ovSessionId)}`, {\n      timeoutMs: 5000,\n      ...options,\n    })\n  }\n\n  /** The identity this client reads as. Only a last-resort path fallback. */\n  get user(): string {\n    return this.connection.user\n  }\n\n  /**\n   * List the `history/archive_00N` directories under a session.\n   *\n   * Takes the session's own `viking://` URI rather than an id: building the path\n   * from this client's configured user silently returned nothing for sessions\n   * owned by another user or peer, which then looked like \"never committed\".\n   */\n  async listHistory(sessionUri: string, options: RequestOptions = {}): Promise<OvResult<OvFsEntry[]>> {\n    const uri = `${sessionUri.replace(/\\/+$/, '')}/history`\n    return this.request<OvFsEntry[]>(`/api/v1/fs/ls?uri=${encodeURIComponent(uri)}`, {\n      timeoutMs: 5000,\n      ...options,\n    })\n  }\n\n  /** Commit tasks for one session. Records are pruned over time — not history. */\n  async listCommitTasks(ovSessionId: string, options: RequestOptions = {}): Promise<OvResult<OvCommitTask[]>> {\n    const query = `task_type=session_commit&resource_id=${encodeURIComponent(ovSessionId)}`\n    const response = await this.request<OvCommitTask[] | { items?: OvCommitTask[] }>(\n      `/api/v1/tasks?${query}`,\n      { timeoutMs: 5000, ...options },\n    )\n    if (!response.ok) return response as OvResult<OvCommitTask[]>\n    const raw = response.result\n    const items = Array.isArray(raw) ? raw : Array.isArray(raw?.items) ? raw.items : []\n    return { ...response, result: items }\n  }\n\n  /**\n   * Read a text file out of `viking://`.\n   *\n   * `content/read` nests the file body inside the envelope, and for JSON files\n   * the body is itself a JSON *string* — callers that expect JSON must parse\n   * twice (`readJson` below).\n   */\n  async readText(uri: string, options: RequestOptions = {}): Promise<OvResult<string>> {\n    const response = await this.request<unknown>(\n      `/api/v1/content/read?uri=${encodeURIComponent(uri)}`,\n      { timeoutMs: 8000, ...options },\n    )\n    if (!response.ok) return response as OvResult<string>\n    return { ...response, result: typeof response.result === 'string' ? response.result : null }\n  }\n\n  /** Read a `viking://` file that holds JSON, tolerating the double encoding. */\n  async readJson<T>(uri: string, options: RequestOptions = {}): Promise<OvResult<T>> {\n    const text = await this.readText(uri, options)\n    if (!text.ok || text.result === null) return text as OvResult<T>\n    return { ...text, result: parseMaybeDoubleEncoded<T>(text.result) }\n  }\n\n  /**\n   * Session-aware retrieval — the call the memory plugin itself makes.\n   *\n   * `session_id` is what makes the answer session-specific: the server applies\n   * its own peer penalties and cross-turn de-duplication against that session, so\n   * the same query under two sessions legitimately ranks differently. The reply\n   * carries every bucket at once plus the server's `query_plan`.\n   */\n  async search(body: OvSearchRequest, options: RequestOptions = {}): Promise<OvResult<OvSearchResponse>> {\n    return this.request<OvSearchResponse>('/api/v1/search/search', { timeoutMs: 12000, ...options }, {\n      method: 'POST',\n      body,\n    })\n  }\n}\n\n/** One retrieval request. Field names are the server's, snake_case included. */\nexport interface OvSearchRequest {\n  query: string\n  /** The `viking://` subtree to rank within. */\n  target_uri: string\n  limit: number\n  /** 0 keeps weak matches visible instead of hiding them behind the default. */\n  score_threshold?: number\n  session_id?: string\n}\n\n/** One retrieved entry, exactly as the server ranks it. */\nexport interface OvSearchItem {\n  uri: string\n  score: number\n  context_type?: string\n  level?: number\n  abstract?: string\n  tags?: string[]\n}\n\n/**\n * A retrieval reply. The three buckets are always present (empty when nothing\n * matched); `query_plan` explains the retrieval and is absent on some servers.\n */\nexport interface OvSearchResponse {\n  memories?: OvSearchItem[]\n  resources?: OvSearchItem[]\n  skills?: OvSearchItem[]\n  total?: number\n  query_plan?: { reasoning?: string } & Record<string, unknown>\n}\n\n/** Everything OpenViking's `content/read` returns is base64-free text, but the\n * envelope sometimes wraps JSON in a JSON string; parse until it stops or we\n * run out of nesting. */\nexport function parseMaybeDoubleEncoded<T>(raw: string): T | null {\n  let value: unknown = raw\n  for (let depth = 0; depth < 3; depth += 1) {\n    if (typeof value !== 'string') break\n    try {\n      value = JSON.parse(value)\n    } catch {\n      return null\n    }\n  }\n  return (value ?? null) as T | null\n}\n\n/** Pull the `result` field out of an enveloped response, or the body itself. */\nfunction unwrap<T>(body: unknown): T | null {\n  if (body === null || typeof body !== 'object') return (body as T) ?? null\n  const record = body as Record<string, unknown>\n  if ('result' in record) return (record.result as T) ?? null\n  return record as T\n}\n\nfunction extractError(body: unknown): string | null {\n  if (body === null || typeof body !== 'object') return null\n  const record = body as Record<string, unknown>\n  const error = record.error\n  if (error && typeof error === 'object') {\n    const message = (error as Record<string, unknown>).message\n    if (typeof message === 'string') return message\n  }\n  if (typeof error === 'string') return error\n  return null\n}\n"
    },
    {
      "path": "src/client/config-page.tsx",
      "content": "/**\n * This plugin's row configuration on the Plugins page.\n *\n * The Plugins page gives a row a **Configure** control only while something\n * registers here, so without this file the plugin's settings existed for the\n * Loader and for agents but not for a person in the GUI: without a registration\n * here the page renders no **Configure** control to open.\n * The page itself owns the values: it reads the entry's volatile fields and\n * hands this component a snapshot plus one atomic write — nothing here talks to\n * the Host directly, and a write is validated against the plugin's `Config`\n * before it is persisted.\n *\n * Editing rules, all of them the page's contract rather than this file's ideas:\n *\n *  - the resolved value is what the plugin runs with; the *base* is the layer it\n *    reverts to when a field is cleared, and a field is \"overridden\" when it is\n *    present in the raw user layer — not when its value differs (an override\n *    equal to the default is still an override);\n *  - every edit is staged locally and submitted in ONE `mutate` carrying the\n *    revision this component read, so a concurrent write is refused instead of\n *    silently overwriting it, and a refusal keeps the draft for a retry;\n *  - clearing a field is an `unset`, which restores inheritance rather than\n *    writing an empty string.\n */\nimport { useCallback, useState } from 'react'\nimport type { PluginConfigViewProps } from '@deepseek-ai/dsh-client-ui-plugin-manager/client'\nimport { configOps } from './config-ops.ts'\nimport { probeEndpoint } from './host-api.ts'\nimport { t } from './locale.ts'\n\ninterface FieldSpec {\n  readonly key: string\n  readonly label: string\n  readonly hint: string\n  readonly placeholder?: string\n  readonly secret?: boolean\n  readonly numeric?: boolean\n}\n\n/** The Config fields in the order a person should meet them. */\nconst FIELDS: readonly FieldSpec[] = [\n  {\n    key: 'endpoint',\n    label: 'config.endpoint',\n    hint: 'config.endpointHint',\n    placeholder: 'http://127.0.0.1:1933',\n  },\n  { key: 'apiKey', label: 'config.apiKey', hint: 'config.apiKeyHint', secret: true },\n  { key: 'account', label: 'config.account', hint: 'config.accountHint' },\n  { key: 'user', label: 'config.user', hint: 'config.userHint' },\n  { key: 'studioPath', label: 'config.studioPath', hint: 'config.studioPathHint', placeholder: '/studio/' },\n  { key: 'cacheTtlMs', label: 'config.cacheTtl', hint: 'config.cacheTtlHint', numeric: true, placeholder: '2500' },\n  { key: 'recallCacheTtlMs', label: 'config.recallCacheTtl', hint: 'config.recallCacheTtlHint', numeric: true, placeholder: '15000' },\n]\n\nconst SECRET_PLACEHOLDER = '••••••••'\n\n/** One value as an input shows it. `undefined`/`null` are an empty field. */\nfunction asText(value: unknown): string {\n  if (value === undefined || value === null) return ''\n  return typeof value === 'string' ? value : String(value)\n}\n\n/**\n * The row's one-liner, shown where the page wants a `summary`.\n *\n * A row whose package has no description falls back to this, so it says what the\n * plugin is pointed at rather than repeating the package name.\n */\nfunction SummaryLine({ form }: { form: PluginConfigViewProps['form'] }) {\n  const resolved = (form?.state.value ?? {}) as Record<string, unknown>\n  const endpoint = asText(resolved.endpoint)\n  return <span>{endpoint.length > 0 ? `OpenViking · ${endpoint}` : t('config.summaryUnset')}</span>\n}\n\nexport function ConfigPage(props: PluginConfigViewProps) {\n  if (props.view === 'summary') return <SummaryLine form={props.form} />\n  return <ConfigForm form={props.form} />\n}\n\nfunction ConfigForm({ form }: { form: PluginConfigViewProps['form'] }) {\n  const [draft, setDraft] = useState<Record<string, string>>({})\n  const [busy, setBusy] = useState(false)\n  const [note, setNote] = useState<{ tone: 'ok' | 'bad'; text: string } | null>(null)\n  const [probe, setProbe] = useState<string | null>(null)\n\n  const state = form?.state\n  const resolved = (state?.value ?? {}) as Record<string, unknown>\n  const overrides = (state?.user ?? {}) as Record<string, unknown>\n  const base = (state?.base ?? {}) as Record<string, unknown>\n  const writable = state?.writable === true\n\n  const valueOf = useCallback(\n    (field: FieldSpec): string => draft[field.key] ?? (field.secret && field.key in overrides ? SECRET_PLACEHOLDER : asText(resolved[field.key])),\n    [draft, overrides, resolved],\n  )\n\n  const stage = (key: string, value: string) => {\n    setDraft((current) => ({ ...current, [key]: value }))\n    setNote(null)\n  }\n\n  const clear = (key: string) => {\n    setDraft((current) => ({ ...current, [key]: '' }))\n    setNote(null)\n  }\n\n  const save = async () => {\n    if (form === undefined) return\n    // Staging → operations is pure and tested on its own (`config-ops.ts`); this\n    // only words the refusal.\n    const result = configOps(FIELDS, draft)\n    if (!result.ok) {\n      const field = FIELDS.find((candidate) => candidate.key === result.field)\n      setNote({\n        tone: 'bad',\n        text: t('config.needNumber', { label: field === undefined ? result.field : t(field.label) }),\n      })\n      return\n    }\n    const ops = result.ops\n    if (ops.length === 0) {\n      setNote({ tone: 'ok', text: t('config.noChanges') })\n      return\n    }\n    setBusy(true)\n    try {\n      // The revision read with the snapshot is the fence: a write against a\n      // namespace someone else changed comes back false, and the draft stays.\n      const accepted = await form.mutate(ops, state?.revision)\n      if (accepted) {\n        setDraft({})\n        setNote({ tone: 'ok', text: t('config.saved') })\n      } else {\n        setNote({ tone: 'bad', text: t('config.refused') })\n      }\n    } catch (error) {\n      setNote({ tone: 'bad', text: error instanceof Error ? error.message : String(error) })\n    } finally {\n      setBusy(false)\n    }\n  }\n\n  const test = async () => {\n    const candidate = valueOf(FIELDS[0] as FieldSpec).trim()\n    setProbe(t('config.checking'))\n    const answer = await probeEndpoint(candidate)\n    // One route error has copy of its own; anything else is a diagnostic and is\n    // shown as the host wrote it.\n    if (!answer.ok) setProbe(answer.error === 'endpoint-not-loopback' ? t('config.probeRefused') : answer.error)\n    else if (answer.reachable) setProbe(t('config.probeOk', { version: answer.version ?? t('config.probeVersionUnknown') }))\n    else setProbe(t('config.probeFailed', { error: answer.error ?? t('config.unknownError') }))\n  }\n\n  if (state === undefined || state.status === 'loading') {\n    return <p className=\"ove-config-note\">{t('config.loading')}</p>\n  }\n  if (state.status === 'unavailable') {\n    return (\n      <p className=\"ove-config-note\">\n        {t('config.unavailable')}\n      </p>\n    )\n  }\n\n  return (\n    <div className=\"ove-config\">\n      {!writable && <p className=\"ove-config-note\">{t('config.readonly')}</p>}\n      {FIELDS.map((field) => (\n        <label className=\"ove-config-field\" key={field.key}>\n          <span className=\"ove-config-label\">\n            {t(field.label)}\n            {field.key in overrides && <span className=\"ove-config-badge\">{t('config.overridden')}</span>}\n          </span>\n          <span className=\"ove-config-control\">\n            <input\n              className=\"ove-config-input\"\n              type={field.secret ? 'password' : 'text'}\n              value={valueOf(field)}\n              placeholder={field.placeholder ?? (field.key in base ? asText(base[field.key]) : '')}\n              spellCheck={false}\n              disabled={!writable || busy}\n              onChange={(event) => stage(field.key, event.target.value)}\n            />\n            {field.key === 'endpoint' && (\n              <button type=\"button\" className=\"ove-config-button\" onClick={() => void test()} disabled={busy}>\n                {t('config.check')}\n              </button>\n            )}\n            <button\n              type=\"button\"\n              className=\"ove-config-button\"\n              title={t('config.defaultHint')}\n              onClick={() => clear(field.key)}\n              disabled={!writable || busy}\n            >\n              {t('config.default')}\n            </button>\n          </span>\n          <span className=\"ove-config-hint\">{t(field.hint)}</span>\n        </label>\n      ))}\n\n      {probe !== null && <p className=\"ove-config-note\">{probe}</p>}\n      {note !== null && (\n        <p className={note.tone === 'ok' ? 'ove-config-note' : 'ove-config-error'}>{note.text}</p>\n      )}\n\n      <div className=\"ove-config-actions\">\n        <button type=\"button\" className=\"ove-config-primary\" onClick={() => void save()} disabled={!writable || busy}>\n          {t('config.save')}\n        </button>\n        <button\n          type=\"button\"\n          className=\"ove-config-button\"\n          onClick={() => {\n            setDraft({})\n            setNote(null)\n          }}\n          disabled={busy || Object.keys(draft).length === 0}\n        >\n          {t('config.discard')}\n        </button>\n      </div>\n    </div>\n  )\n}\n"
    }
  ],
